func TestCircuitKindOpenAI(t *testing.T) {
	err := newCircuitError(circuitKindOpenAI)
	if got := CircuitKind(err); got != "openai" {
		t.Errorf("CircuitKind(openai) = %q, want %q", got, "openai")
	}
